import sys

def solve():
    s = sys.stdin.read().strip()
    if not s:
        print(0)
        return

    # current_nodes: list of (label, count)
    current_nodes = [(1, 1)]

    for char in s:
        next_nodes = {}
        for label, count in current_nodes:
            if char == 'L':
                new_label = label * 2
                next_nodes[new_label] = next_nodes.get(new_label, 0) + count
            elif char == 'R':
                new_label = label * 2 + 1
                next_nodes[new_label] = next_nodes.get(new_label, 0) + count
            elif char == 'P':
                new_label = label
                next_nodes[new_label] = next_nodes.get(new_label, 0) + count
            elif char == '*':
                # Try all three moves
                new_label_L = label * 2
                next_nodes[new_label_L] = next_nodes.get(new_label_L, 0) + count
                new_label_R = label * 2 + 1
                next_nodes[new_label_R] = next_nodes.get(new_label_R, 0) + count
                new_label_P = label
                next_nodes[new_label_P] = next_nodes.get(new_label_P, 0) + count
        current_nodes = list(next_nodes.items())

    total_value = sum(label * count for label, count in current_nodes)
    print(total_value)

if __name__ == "__main__":
    solve()
